module avalon_master_arbiter_2m_256 (
    input  logic         clk_i,
    input  logic         rstn_i,
    output logic         drain_idle_o,

    // Realtime guard generated by the camera writer / HDMI prefetch path.
    // When asserted while IDLE, AI is not allowed to launch a new DDR command.
    // Master 0 still has priority and an already accepted transaction is never
    // preempted.
    input  logic         realtime_guard_i,

    // Master 0: existing camera/HDMI framebuffer reader.
    // HARD PRIORITY whenever the arbiter is idle.
    input  logic         m0_read_i,
    input  logic         m0_write_i,
    input  logic [255:0] m0_writedata_i,
    input  logic [31:0]  m0_address_i,
    input  logic [31:0]  m0_byteenable_i,
    input  logic [10:0]  m0_burstcount_i,
    output logic [255:0] m0_readdata_o,
    output logic         m0_readdatavalid_o,
    output logic         m0_waitrequest_o,

    // Master 1: HandSeg AI master. It is background traffic only.
    input  logic         m1_read_i,
    input  logic         m1_write_i,
    input  logic [255:0] m1_writedata_i,
    input  logic [31:0]  m1_address_i,
    input  logic [31:0]  m1_byteenable_i,
    input  logic [10:0]  m1_burstcount_i,
    output logic [255:0] m1_readdata_o,
    output logic         m1_readdatavalid_o,
    output logic         m1_waitrequest_o,

    // Single Qsys interconnect master port.
    output logic         s_read_o,
    output logic         s_write_o,
    output logic [255:0] s_writedata_o,
    output logic [31:0]  s_address_o,
    output logic [31:0]  s_byteenable_o,
    output logic [10:0]  s_burstcount_o,
    input  logic [255:0] s_readdata_i,
    input  logic         s_readdatavalid_i,
    input  logic         s_waitrequest_i
);

    // V4.3 arbitration policy:
    //
    //   1. Camera/HDMI read (master 0) has absolute priority at IDLE.
    //   2. AI may launch a new transaction only if:
    //          - master 0 is not requesting, AND
    //          - realtime_guard_i is low.
    //   3. Once accepted, a transaction is allowed to finish. Avalon requests
    //      are never cut in the middle of a burst/read response.
    //   4. V4.6 AI traffic may use burstcount up to 8. A realtime request
    //      arriving just after AI acceptance waits only for that already
    //      accepted burst to complete; new AI bursts remain blocked by guard.
    //
    // realtime_guard_i is intentionally NOT "camera frame active". Blocking AI
    // for an entire camera frame would prevent the streaming model-input writer
    // from draining its CDC FIFO. The guard represents actual framebuffer DDR
    // urgency (camera burst pending/active or HDMI prefetch pending/active).

    typedef enum logic [1:0] {
        A_IDLE,
        A_READ_RSP,
        A_WRITE_BURST
    } astate_t;

    astate_t state_r;
    assign drain_idle_o = (state_r == A_IDLE);
    logic owner_r;                 // 0=camera/HDMI, 1=AI
    logic [10:0] beats_left_r;

    logic have0_c;
    logic have1_c;
    logic grant0_c;
    logic grant1_c;

    assign have0_c  = m0_read_i | m0_write_i;
    assign have1_c  = m1_read_i | m1_write_i;
    assign grant0_c = have0_c;
    assign grant1_c = (~have0_c) & have1_c & (~realtime_guard_i);

    always_comb begin
        s_read_o       = 1'b0;
        s_write_o      = 1'b0;
        s_writedata_o  = 256'd0;
        s_address_o    = 32'd0;
        s_byteenable_o = 32'd0;
        s_burstcount_o = 11'd1;

        m0_readdata_o      = s_readdata_i;
        m1_readdata_o      = s_readdata_i;
        m0_readdatavalid_o = 1'b0;
        m1_readdatavalid_o = 1'b0;

        // Default to stalled. Only the currently granted/owned master sees the
        // downstream waitrequest. This is what keeps AI valid asserted safely
        // while a realtime guard is active.
        m0_waitrequest_o = 1'b1;
        m1_waitrequest_o = 1'b1;

        case (state_r)
            A_IDLE: begin
                if (grant0_c) begin
                    s_read_o         = m0_read_i;
                    s_write_o        = m0_write_i;
                    s_writedata_o    = m0_writedata_i;
                    s_address_o      = m0_address_i;
                    s_byteenable_o   = m0_byteenable_i;
                    s_burstcount_o   = (m0_burstcount_i == 0) ? 11'd1
                                                             : m0_burstcount_i;
                    m0_waitrequest_o = s_waitrequest_i;
                end
                else if (grant1_c) begin
                    s_read_o         = m1_read_i;
                    s_write_o        = m1_write_i;
                    s_writedata_o    = m1_writedata_i;
                    s_address_o      = m1_address_i;
                    s_byteenable_o   = m1_byteenable_i;
                    s_burstcount_o   = (m1_burstcount_i == 0) ? 11'd1
                                                             : m1_burstcount_i;
                    m1_waitrequest_o = s_waitrequest_i;
                end
            end

            A_READ_RSP: begin
                if (!owner_r) begin
                    m0_readdatavalid_o = s_readdatavalid_i;
                    m0_readdata_o      = s_readdata_i;
                end
                else begin
                    m1_readdatavalid_o = s_readdatavalid_i;
                    m1_readdata_o      = s_readdata_i;
                end
            end

            A_WRITE_BURST: begin
                if (!owner_r) begin
                    s_write_o         = m0_write_i;
                    s_writedata_o     = m0_writedata_i;
                    s_address_o       = m0_address_i;
                    s_byteenable_o    = m0_byteenable_i;
                    s_burstcount_o    = (m0_burstcount_i == 0) ? 11'd1
                                                               : m0_burstcount_i;
                    m0_waitrequest_o  = s_waitrequest_i;
                end
                else begin
                    s_write_o         = m1_write_i;
                    s_writedata_o     = m1_writedata_i;
                    s_address_o       = m1_address_i;
                    s_byteenable_o    = m1_byteenable_i;
                    s_burstcount_o    = (m1_burstcount_i == 0) ? 11'd1
                                                               : m1_burstcount_i;
                    m1_waitrequest_o  = s_waitrequest_i;
                end
            end

            default: begin end
        endcase
    end

    always_ff @(posedge clk_i or negedge rstn_i) begin
        if (!rstn_i) begin
            state_r      <= A_IDLE;
            owner_r      <= 1'b0;
            beats_left_r <= 11'd0;
        end
        else begin
            case (state_r)
                A_IDLE: begin
                    // A transaction is accepted only when one of the explicit
                    // grants is active and the downstream slave accepts it.
                    if ((grant0_c || grant1_c) &&
                        (s_read_o || s_write_o) && !s_waitrequest_i) begin
                        owner_r <= grant1_c;

                        if (s_read_o) begin
                            beats_left_r <= s_burstcount_o;
                            state_r      <= A_READ_RSP;
                        end
                        else begin
                            if (s_burstcount_o > 1) begin
                                beats_left_r <= s_burstcount_o - 1'b1;
                                state_r      <= A_WRITE_BURST;
                            end
                            else begin
                                beats_left_r <= 11'd0;
                                state_r      <= A_IDLE;
                            end
                        end
                    end
                end

                A_READ_RSP: begin
                    if (s_readdatavalid_i) begin
                        if (beats_left_r <= 1) begin
                            beats_left_r <= 11'd0;
                            state_r      <= A_IDLE;
                        end
                        else begin
                            beats_left_r <= beats_left_r - 1'b1;
                        end
                    end
                end

                A_WRITE_BURST: begin
                    if (s_write_o && !s_waitrequest_i) begin
                        if (beats_left_r <= 1) begin
                            beats_left_r <= 11'd0;
                            state_r      <= A_IDLE;
                        end
                        else begin
                            beats_left_r <= beats_left_r - 1'b1;
                        end
                    end
                end

                default: begin
                    state_r      <= A_IDLE;
                    owner_r      <= 1'b0;
                    beats_left_r <= 11'd0;
                end
            endcase
        end
    end

endmodule
